{"command":"cd /testbed/release-mgmt/release/RB-42 && python3 - <<'EOF'
import hashlib, json, os
m = json.load(open('manifest.json'))
def sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for b in iter(lambda: f.read(65536), b''): h.update(b)
    return h.hexdigest()
print("manifest entries:", len(m['artifacts']))
ok=bad=missing=0
for e in m['artifacts']:
    p=e['path']
    if not os.path.exists(p):
        print(f"  MISSING  {p}"); missing+=1
    elif sha(p)==e['sha256']:
        print(f"  OK       {p}"); ok+=1
    else:
        print(f"  MISMATCH {p}\n           want {e['sha256']}\n           got  {sha(p)}"); bad+=1
print(f"\nverified={ok} failed={bad} missing={missing} total_manifest={len(m['artifacts'])}")
print("complete?", ok==len(m['artifacts']) and missing==0 and bad==0)
print("manifest_digest:", sha('manifest.json'))
EOF"}

